#!/usr/bin/env node
/**
 * Generate `editions.json` — the map from source rows to the LANGUAGE EDITIONS a quickstart's archive ships.
 *
 * WHY THIS FILE EXISTS: Tracy Business ships 43 language editions, 41 of them generated by `tools/add-language.php`
 * from the en edition (own menutype `tb-*-<sef>`, megamenu keyed by the edition's ids, module "(sef)", article
 * `-<sef>`). A translation that makes a COPY of the source puts the copy in menu `tb-main-en`, while the template reads
 * `tb-main-<sef>` — measured 23/09/2026 on j-ee6vsk: the `/vi/` page lost its main menu. The right path is to ADOPT
 * the archive's edition and write the text into it (settled 23/09). The Claude Cowork plugin needs to know which edition
 * row matches which source row, and the ids are fixed per release — so the map is GENERATED once from that release's
 * own dump, not guessed at run time.
 *
 * 🔒 RULES, NOT A SNAPSHOT. The file keeps only ids, the category table, the menutype table and sef. The Claude Cowork
 * plugin builds the expectation for an adopted row from the rules of `add-language.php` (language; article alias
 * `-<sef>`; catid; menutype; parent/link/aliasoptions; module title `(en)`→`(sef)`; menutype in params).
 * This generator CHECKS every row pair of every language edition against those rules on the real archive, and
 * refuses to generate if a field outside the text cells drifts — so the rules cannot silently go wrong for the archive.
 *
 * Run: `node scripts/build-joomla-editions.mjs --contract tracy-business/j6/1.1.0 --dump <db.sql.gz>`
 *       add `--check` to compare with the committed file instead of writing.
 */
import { createHash } from 'node:crypto'
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { gunzipSync } from 'node:zlib'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const CONTRACTS = path.join(ROOT, 'packages/cms/tracy-joomla-quickstart/contracts')

const arg = (name) => {
  const at = process.argv.indexOf(name)
  return at === -1 ? null : process.argv[at + 1]
}
const contractId = arg('--contract')
const dumpFile = arg('--dump')
const CHECK_ONLY = process.argv.includes('--check')
if (!contractId || !dumpFile) {
  console.error('usage: build-joomla-editions.mjs --contract <id> --dump <database.sql.gz> [--check]')
  process.exit(2)
}
const dir = path.join(CONTRACTS, contractId)
const readJson = (file) => JSON.parse(readFileSync(file, 'utf8'))
const contentMap = readJson(path.join(dir, 'content-map.json'))
const lock = readJson(path.join(dir, 'presentation-lock.json'))
const profile = readJson(path.join(dir, 'multilingual-map.json'))
const SOURCE = profile.sourceLanguage

/* ------------------------------------------------------------------ the dump */

/** Rows of one table from a mysqldump: the column names from CREATE TABLE, the values from INSERT. */
function tableRows(sql, table) {
  const create = sql.indexOf('CREATE TABLE `' + table + '` (')
  if (create === -1) throw new Error(`the dump has no table ${table}`)
  const columns = []
  for (const line of sql.slice(create, sql.indexOf(') ENGINE=', create)).split('\n').slice(1)) {
    const m = /^\s+`([^`]+)`/.exec(line)
    if (m) columns.push(m[1])
  }
  const rows = []
  let at = sql.indexOf('INSERT INTO `' + table + '` VALUES', create)
  while (at !== -1) {
    let i = sql.indexOf('VALUES', at) + 6
    for (;;) {
      while (sql[i] !== '(') i += 1
      i += 1
      const values = []
      for (;;) {
        while (sql[i] === ' ' || sql[i] === '\n') i += 1
        if (sql[i] === "'") {
          let out = ''
          i += 1
          for (;;) {
            const c = sql[i]
            if (c === '\\') {
              const n = sql[i + 1]
              out += { n: '\n', r: '\r', t: '\t', 0: '\0', Z: '\x1a', b: '\b' }[n] ?? n
              i += 2
            } else if (c === "'") {
              if (sql[i + 1] === "'") {
                out += "'"
                i += 2
              } else {
                i += 1
                break
              }
            } else {
              out += c
              i += 1
            }
          }
          values.push(out)
        } else {
          let j = i
          while (sql[j] !== ',' && sql[j] !== ')') j += 1
          const raw = sql.slice(i, j).trim()
          values.push(raw === 'NULL' ? null : raw)
          i = j
        }
        while (sql[i] === ' ' || sql[i] === '\n') i += 1
        if (sql[i] === ',') {
          i += 1
          continue
        }
        if (sql[i] === ')') {
          i += 1
          break
        }
        throw new Error(`unexpected ${sql.slice(i, i + 20)} in ${table}`)
      }
      rows.push(Object.fromEntries(columns.map((c, k) => [c, values[k]])))
      while (sql[i] === ' ' || sql[i] === '\n') i += 1
      if (sql[i] === ',') {
        i += 1
        continue
      }
      break
    }
    at = sql.indexOf('INSERT INTO `' + table + '` VALUES', i)
  }
  return rows
}

// The dump's table prefix is the one the lock was captured with (`ng_` for Business).
const raw = readFileSync(dumpFile)
const sql = (dumpFile.endsWith('.gz') ? gunzipSync(raw) : raw).toString('utf8')
const prefix = /CREATE TABLE `([a-z0-9]+_)menu` \(/.exec(sql)?.[1]
if (!prefix) throw new Error('no #__menu table in the dump')
const menu = tableRows(sql, `${prefix}menu`).filter((r) => r.client_id === '0')
const modules = tableRows(sql, `${prefix}modules`).filter((r) => r.client_id === '0')
const articles = tableRows(sql, `${prefix}content`)
const categories = tableRows(sql, `${prefix}categories`).filter((r) => r.extension === 'com_content')
const byId = (rows) => new Map(rows.map((r) => [Number(r.id), r]))
const MENU = byId(menu)
const MODULE = byId(modules)
const ARTICLE = byId(articles)

/* ------------------------------------------------------------------ the map */

const entities = new Map(contentMap.entities.map((e) => [e.key, e]))
const translated = contentMap.entities.filter((e) => profile.policies[e.key]?.policy === 'translate')
const slotColumns = new Map()
for (const slot of contentMap.slots) {
  if (!slotColumns.has(slot.entity)) slotColumns.set(slot.entity, new Set())
  slotColumns.get(slot.entity).add(slot.column)
}
const sefOfMenutype = (mt) => /^tb-main-(.+)$/.exec(mt)?.[1] ?? null
const sourceSef = sefOfMenutype(
  menu.find((r) => r.language === SOURCE && r.menutype.startsWith('tb-main-'))?.menutype ?? ''
)
if (!sourceSef) throw new Error(`no tb-main-* menu in ${SOURCE}`)
// Every language whose main menu the archive ships, except the source and any the contract already
// governs row by row (ru-RU on Business: its rows are in the lock, and the seeder writes them).
const governedLanguages = new Set(contentMap.entities.map((e) => e.identity.language).filter(Boolean))
const locales = [...new Set(menu.filter((r) => r.menutype.startsWith('tb-main-')).map((r) => r.language))]
  .filter((l) => l !== SOURCE && l !== '*' && !governedLanguages.has(l))
  .sort()

const swapSuffix = (value, sef) => value.replace(new RegExp(`-${sourceSef}$`), `-${sef}`)

const out = {
  schemaVersion: 'tracy-quickstart-editions/v1',
  contract: contractId,
  baseHash: profile.baseHash,
  source: { language: SOURCE, sef: sourceSef },
  locales: {}
}
const problems = []
for (const locale of locales) {
  const sef = sefOfMenutype(
    menu.find((r) => r.language === locale && r.menutype.startsWith('tb-main-')).menutype
  )
  const ids = {}
  const menutypes = {}
  // Whole-table maps, not only the translated rows: a link or a module's params may point at any
  // article, menu item or category of the edition (`view=category&id=253` → the edition's own).
  const tag = locale.replace('-', '').toLowerCase()
  // A category alias repeats under different parents (`projects` at the root and under `news`), so
  // a category is matched by its alias AND its already-matched parent, from the root down.
  const categoryMap = {}
  const sourceCategories = categories
    .filter((r) => r.language === SOURCE)
    .sort((a, b) => Number(a.level) - Number(b.level))
  for (const c of sourceCategories) {
    const parent = c.parent_id === '1' ? '1' : String(categoryMap[c.parent_id] ?? '')
    const found = categories.filter(
      (r) => r.language === locale && r.alias === `${c.alias}-${tag}` && r.parent_id === parent
    )
    if (found.length === 1) categoryMap[c.id] = Number(found[0].id)
  }
  const articleMap = {}
  for (const a of articles.filter((r) => r.language === SOURCE)) {
    const found = articles.filter((r) => r.language === locale && r.alias === `${a.alias}-${sef}`)
    if (found.length === 1) articleMap[a.id] = Number(found[0].id)
  }
  const menuMap = {}
  for (const m of menu.filter((r) => r.language === SOURCE && /-[a-z-]+$/.test(r.menutype))) {
    const found = menu.filter(
      (r) => r.language === locale && r.menutype === swapSuffix(m.menutype, sef) && r.path === m.path
    )
    if (found.length === 1) menuMap[m.id] = Number(found[0].id)
  }
  for (const entity of translated) {
    const source =
      entity.kind === 'menuItem'
        ? MENU.get(entity.sourceId)
        : entity.kind === 'article'
          ? ARTICLE.get(entity.sourceId)
          : entity.kind === 'module'
            ? MODULE.get(entity.sourceId)
            : null
    if (!source) continue
    let found = []
    if (entity.kind === 'menuItem')
      found = menu.filter(
        (r) =>
          r.language === locale && r.menutype === swapSuffix(source.menutype, sef) && r.path === source.path
      )
    else if (entity.kind === 'article')
      found = articles.filter((r) => r.language === locale && r.alias === `${source.alias}-${sef}`)
    else
      found = modules.filter(
        (r) =>
          r.language === locale &&
          r.module === source.module &&
          r.position === source.position &&
          r.ordering === source.ordering
      )
    if (found.length !== 1) {
      problems.push(`${locale} ${entity.key}: ${found.length} candidate rows`)
      continue
    }
    const edition = found[0]
    ids[entity.key] = Number(edition.id)
    if (entity.kind === 'menuItem') menutypes[source.menutype] = edition.menutype
  }
  out.locales[locale] = {
    sef,
    ids,
    menutypes,
    maps: { article: articleMap, menuItem: menuMap, category: categoryMap }
  }
}

/* ------------------------------------------------------------------ the proof */

// Each edition row must equal its source under the add-language rules, field by field, outside the
// slot columns. Anything else is a difference the Claude Cowork plugin would call drift on a customer's site.
const idMaps = (locale) => out.locales[locale].maps
const remapLink = (link, map, sef) =>
  link
    .replace(/(view=article&id=)(\d+)/, (m, p, id) => p + (map.article[id] ?? id))
    .replace(/(view=category(?:&[a-z_]+=[^&]*)*&id=)(\d+)/, (m, p, id) => p + (map.category[id] ?? id))
    .replace(/(Itemid=)(\d+)/, (m, p, id) => p + (map.menuItem[id] ?? id))
    .replace(new RegExp(`^/${sourceSef}/`), `/${sef}/`)
/** A JA block's config (a JSON string inside the JSON): its `[source-category]` and `[selected]` ids. */
const editionRefs = (params, map) => {
  const walk = (node) => {
    if (Array.isArray(node)) return node.map(walk)
    if (!node || typeof node !== 'object') return node
    const out = {}
    for (const [k, v] of Object.entries(node)) {
      const table = k.endsWith('[source-category]')
        ? map.category
        : k.endsWith('[selected]')
          ? map.article
          : null
      out[k] = table ? (Array.isArray(v) ? v.map((i) => table[i] ?? i) : (table[v] ?? v)) : walk(v)
    }
    return out
  }
  if (typeof params['jatools-config'] === 'string')
    return { ...params, 'jatools-config': walk(JSON.parse(params['jatools-config'])) }
  return params
}
const remapCatids = (params, map) =>
  params.replace(
    /("catid":\[)([\d,"]*)(\])/g,
    (m, a, list, b) => a + list.replace(/\d+/g, (id) => String(map.category[id] ?? id)) + b
  )
for (const locale of Object.keys(out.locales)) {
  const { sef, ids, menutypes } = out.locales[locale]
  const map = idMaps(locale)
  for (const [key, id] of Object.entries(ids)) {
    const entity = entities.get(key)
    const kind = entity.kind
    const table = kind === 'menuItem' ? MENU : kind === 'article' ? ARTICLE : MODULE
    const source = table.get(entity.sourceId)
    const edition = table.get(id)
    const want = { ...source, language: locale }
    if (kind === 'article') {
      want.alias = `${source.alias}-${sef}`
      want.catid = String(map.category[source.catid] ?? source.catid)
    }
    if (kind === 'menuItem') {
      want.menutype = menutypes[source.menutype]
      want.parent_id = String(map.menuItem[source.parent_id] ?? source.parent_id)
      want.link = remapLink(source.link, map, sef)
      want.params = source.params.replace(/("aliasoptions":)(\d+)/, (m, p, n) => p + (map.menuItem[n] ?? n))
    }
    if (kind === 'module') {
      want.title = source.title.replace(`(${sourceSef})`, `(${sef})`)
      let params = source.params
      for (const [from, to] of Object.entries(menutypes)) params = params.replaceAll(`"${from}"`, `"${to}"`)
      want.params = remapCatids(params, map)
    }
    // A slot column is words AND structure: its words may differ, its ids may not. Every number
    // inside the parameters — a JA block's config included — must be what the rules say.
    if (kind === 'module' && slotColumns.get(key)?.has('params')) {
      const numbers = (value, trail, out) => {
        let node = value
        if (typeof node === 'string' && /^[[{]/.test(node)) {
          try {
            node = JSON.parse(node)
          } catch {}
        }
        if (Array.isArray(node)) node.forEach((v) => numbers(v, trail, out))
        else if (node && typeof node === 'object')
          for (const [k, v] of Object.entries(node)) numbers(v, `${trail}/${k}`, out)
        else if (typeof node === 'number' || (typeof node === 'string' && /^\d+$/.test(node)))
          out.push(`${trail}=${node}`)
        return out
      }
      // A number that IS a slot (a year in a timeline) is a word the edition may have translated.
      const wordAt = new Set(
        contentMap.slots
          .filter((slot) => slot.entity === key && slot.column === 'params' && Array.isArray(slot.jsonPath))
          .map((slot) =>
            `/${slot.nestedJson ?? ''}/${slot.jsonPath.filter((p) => typeof p === 'string').join('/')}`.replace(
              '//',
              '/'
            )
          )
      )
      const numbersOf = (params) =>
        numbers(params, '', []).filter((n) => !wordAt.has(n.slice(0, n.lastIndexOf('='))))
      const ruled = numbersOf(editionRefs(JSON.parse(want.params), map))
      const shipped = numbersOf(JSON.parse(edition.params))
      if (ruled.join() !== shipped.join())
        problems.push(
          `${locale} ${key}.params ids: rule gives ${ruled.filter((x) => !shipped.includes(x)).slice(0, 3)}, archive has ${shipped.filter((x) => !ruled.includes(x)).slice(0, 3)}`
        )
    }
    for (const field of Object.keys(lock.entities[key])) {
      if (slotColumns.get(key)?.has(field)) continue
      if (String(want[field] ?? '') !== String(edition[field] ?? ''))
        problems.push(
          `${locale} ${key}.${field}: rule gives ${JSON.stringify(String(want[field]).slice(0, 60))}, archive has ${JSON.stringify(String(edition[field]).slice(0, 60))}`
        )
    }
  }
  // Rows of the edition the archive published, beside the ones mapped above: shown again with it.
  const mapped = new Set(Object.values(ids))
  out.locales[locale].reveal = {
    module: modules
      .filter((r) => r.language === locale && r.published === '1' && !mapped.has(Number(r.id)))
      .map((r) => Number(r.id)),
    menuItem: menu
      .filter((r) => r.language === locale && r.published === '1' && !mapped.has(Number(r.id)))
      .map((r) => Number(r.id)),
    article: articles
      .filter((r) => r.language === locale && r.state === '1' && !mapped.has(Number(r.id)))
      .map((r) => Number(r.id))
  }
}
if (problems.length) {
  console.error(
    `editions: ${problems.length} difference(s) the rules do not explain:\n  ${problems.slice(0, 20).join('\n  ')}`
  )
  process.exit(1)
}

const file = path.join(dir, 'editions.json')
const text = `${JSON.stringify(out, null, 2)}\n`
const counts = Object.values(out.locales).map((l) => Object.keys(l.ids).length)
if (CHECK_ONLY) {
  if (!existsSync(file) || readFileSync(file, 'utf8') !== text) {
    console.error(
      `editions: ${path.relative(ROOT, file)} differs from what the dump gives; run without --check`
    )
    process.exit(1)
  }
  console.log(`editions: ${contractId} matches the dump (${Object.keys(out.locales).length} languages)`)
} else {
  writeFileSync(file, text)
  console.log(
    `editions: ${contractId} — ${Object.keys(out.locales).length} languages, ${Math.min(...counts)}–${Math.max(...counts)} rows mapped each, sha256 ${createHash('sha256').update(text).digest('hex').slice(0, 12)}`
  )
}
